// The suggested questions and their stored answers (PLAN.md slice 5: Q47, Q54, step 8 D1).
// The default repo's set ships with the page (a static import, so the first screen makes no
// request, even with the backend down). Every other exported repo is one dynamic chunk, loaded
// when the visitor switches to it. A repo with no export has no set: "none", never an error.
// Both modules are generated by `python -m codeask.pregen export`.
import defaultSet from "../data/examples/pallets__itsdangerous/set";
import { LOADERS } from "../data/examples/sets";
import type { Example, StoredSet } from "./types";

// DEFAULT_REPO's set (tests/logic/stored.spec.ts checks they match).
export const DEFAULT_SET = defaultSet as unknown as StoredSet;

export type SetLoad = { kind: "set"; set: StoredSet } | { kind: "none" };
export type Loaders = Record<string, () => Promise<{ default: unknown }>>;

/** Resolves to the repo's set, or "none" when it has no export. Rejects only when its chunk
 *  can't be loaded: the caller keeps the current view and offers to try again. */
export async function loadSet(slug: string, loaders: Loaders = LOADERS): Promise<SetLoad> {
  if (slug === DEFAULT_SET.index.repo) return { kind: "set", set: DEFAULT_SET };
  const load = loaders[slug];
  if (!load) return { kind: "none" };
  const chunk = await load();
  return { kind: "set", set: chunk.default as StoredSet };
}

/** The id of the stored answer to show: the chosen one if the set has it, else the flagship. */
export function shownId(set: StoredSet, chosen: string | null): string {
  return chosen !== null && chosen in set.answers ? chosen : set.index.flagship;
}

export function storedAnswer(set: StoredSet, chosen: string | null): Example {
  return set.answers[shownId(set, chosen)];
}
